'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID(), today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});
const currency=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n||0);
const stages=['Intake','Investigation','Discovery','Demand','Litigation','Settlement','Closed'];
const modules=[['onboarding','✦','Start here · onboarding'],['approvals','✓','Attorney review'],['overview','◫','Overview'],['reception','◉','Maya · reception'],['copilot','✧','Attorney copilot'],['matters','▤','Matters & intake'],['contacts','♧','People & providers'],['tasks','☑','Tasks & deadlines'],['documents','▧','Documents & files'],['communications','◌','Communications'],['finance','＄','Finance & time'],['knowledge','✳','Matter intelligence'],['research','◎','Law monitor'],['agents','⎇','Case preparation'],['connectors','⌘','Service status'],['settings','⚙','Workspace settings']];
async function apiFetch(path,options={}){const headers=new Headers(options.headers||{});if(statusInfo.csrfToken&&!['GET','HEAD'].includes(options.method||'GET'))headers.set('X-CSRF-Token',statusInfo.csrfToken);const r=await fetch(path,{...options,headers});if(r.status===401&&statusInfo.accountMode){location.assign('/login.html');throw Error('Please sign in again.');}return r;}
window.mlawApi=apiFetch;
let state, mode='browser', view='overview', filter='', statusInfo={}, chatHistory=[], chatLanguage='English';
const storeKey='mlaw-next-v1';
async function initialize(){
 const seed=await fetch('/seed.json').then(r=>r.json());
 try{const h=await apiFetch('/api/health');if(h.status===401){location.assign('/login.html');return;}if(h.ok){statusInfo=await h.json();mode='server';const r=await apiFetch('/api/state');if(!r.ok)throw Error('State unavailable');state=await r.json();}}catch{}
 if(!state){try{state=JSON.parse(localStorage.getItem(storeKey))||seed}catch{state=seed}}
 for(const k of Object.keys(seed))if(!Array.isArray(state[k]))state[k]=seed[k];
 if(statusInfo.accountMode){const control=document.createElement('button');control.className='text-button account-chip';control.textContent=statusInfo.user.name+' · '+statusInfo.user.role+' · Sign out';control.onclick=async()=>{await apiFetch('/api/auth/logout',{method:'POST'});location.assign('/login.html');};$('#storageStatus').after(control);}
 $('#storageStatus').textContent=mode==='server'?'● Private firm workspace':'● Demonstration workspace';
 $('#osNav').innerHTML=modules.map(([key,icon,label])=>`<button data-view="${key}"><span>${icon}</span>${label}</button>`).join('');
 document.addEventListener('click',click);$('#closeModal').onclick=()=>$('#modal').close();$('#mobileNav').onclick=()=>$('.sidebar').classList.toggle('open');
 $('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.sidebar').classList.remove('open')});
 $('#motionToggle').onclick=()=>{const paused=document.body.classList.toggle('motion-paused');const v=$('#heroVideo');paused?v.pause():v.play().catch(()=>{});$('#motionToggle').textContent=paused?'▷':'Ⅱ';$('#motionToggle').setAttribute('aria-label',paused?'Resume motion':'Pause motion')};
 $('.hero-visual').addEventListener('pointermove',e=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=e.currentTarget.getBoundingClientRect();$('.sculpture').style.transform=`rotateY(${(e.clientX-r.left-r.width/2)/35}deg) rotateX(${-(e.clientY-r.top-r.height/2)/45}deg)`});
 $('.hero-visual').addEventListener('pointerleave',()=>$('.sculpture').style.transform='');
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)$('#heroVideo').pause();
 window.addEventListener('hashchange',route);route();
}
function route(){const key=location.hash.replace('#os/','');if(location.hash.startsWith('#os/'))openWorkspace(modules.some(x=>x[0]===key)?key:'overview',false)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
async function save(action,detail){state.audit.unshift({id:id(),action,detail,date:new Date().toISOString()});state.audit=state.audit.slice(0,500);if(mode==='server'){const r=await apiFetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not save changes to server.');state=result;}else{try{localStorage.setItem(storeKey,JSON.stringify(state))}catch{throw Error('Browser storage is full. Export records before continuing.')}}}
function openWorkspace(key='overview',hash=true){view=key;$('#site').hidden=true;$('#workspace').hidden=false;if(hash)history.replaceState(null,'',`#os/${key}`);$('.sidebar').classList.remove('open');render();window.scrollTo(0,0)}
function home(){ $('#workspace').hidden=true;$('#site').hidden=false;history.replaceState(null,'',location.pathname);window.scrollTo(0,0)}
function modal(title,body){$('#modalLabel').textContent=title;$('#modalBody').innerHTML=body;if(!$('#modal').open)$('#modal').showModal()}
function heading(label,title,desc,action=''){return `<div class="os-heading"><div><p class="eyebrow">${esc(label)}</p><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function btn(label,action,extra=''){return `<button class="button dark small" data-action="${action}" ${extra}>${label} <span>↗</span></button>`}
function badge(t,color=''){return `<span class="badge ${color}">${esc(t)}</span>`}
function matterOptions(value=''){return state.matters.map(m=>`<option value="${m.id}" ${m.id===value?'selected':''}>${esc(m.name)} · ${m.id}</option>`).join('')}
function matterName(key){return state.matters.find(m=>m.id===key)?.name||key}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No records yet.</td></tr>`}</tbody></table></div>`}
function render(){ $('#breadcrumb').textContent=modules.find(m=>m[0]===view)?.[2]||'Overview';$$('#osNav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#osContent').innerHTML=({onboarding,approvals,overview,reception,copilot,matters,contacts,tasks,documents,communications,finance,knowledge,research,agents,connectors,settings}[view]||overview)();bindView();if(view==='copilot')bindCopilot();if(view==='reception')bindReception();if(view==='onboarding'||view==='approvals')bindOnboarding(view) }
function copilot(){return heading('ATTORNEY COPILOT','Ask the workspace.<br><em>Build the next draft.</em>','Matter-grounded preparation for Adnan and the team. Every answer remains review work product.')+`<div class="os-grid"><div class="panel"><div class="panel-head"><h2>Matter-grounded assistant</h2>${badge(statusInfo.modelConfigured?'Drafting available':'Record-based preview',statusInfo.modelConfigured?'':'amber')}</div><form id="copilotForm" class="form-stack"><label>Matter context<select id="copilotMatter">${matterOptions()}</select></label><label>What would you like to prepare?<textarea id="copilotPrompt" required maxlength="3000" placeholder="Prepare a medical chronology outline and list the evidence we still need."></textarea></label><button class="button dark" id="askCopilot">Prepare response ↗</button></form><p class="subtle">Only the selected matter and linked record metadata are included. Uploaded PDF contents are not parsed. Model responses do not certify legal accuracy or filing readiness.</p></div><div class="panel"><h3>Useful starting points</h3><div class="source-item"><p>“What evidence is missing before a demand?”</p></div><div class="source-item"><p>“Prepare a client update in Spanish.”</p></div><div class="source-item"><p>“Outline a motion and mark facts and authorities still needed.”</p></div><div class="source-item"><p>“Summarize the matter, open tasks and related documents.”</p></div></div></div><div class="panel" id="copilotResult" hidden></div>`}
function bindCopilot(){$('#copilotForm').onsubmit=async e=>{e.preventDefault();const button=$('#askCopilot');button.disabled=true;const m=state.matters.find(x=>x.id===$('#copilotMatter').value),question=$('#copilotPrompt').value;try{let answer;if(mode==='server'&&statusInfo.modelConfigured){const r=await apiFetch('/api/copilot',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matter:m.id,question})});const d=await r.json();if(!r.ok)throw Error(d.error);answer=d.content}else answer=`RECORD SUMMARY — DRAFTING ASSISTANT NEEDS SETUP\n\nRequest: ${question}\n\nMATTER CONTEXT [${m.id}]\nClient: ${m.name}\nStage: ${m.stage}\nAttorney: ${m.owner}\nIncident date: ${m.incident}\nRecorded summary: ${m.summary}\n\nOPEN WORK\n${state.tasks.filter(t=>t.matter===m.id&&!t.done).map(t=>t.title+' — '+t.date).join('\n')||'No open tasks.'}\n\nEVIDENCE INVENTORY\n${state.files.filter(f=>f.matter===m.id).map(f=>f.name+' — contents not analyzed').join('\n')||'No source files supplied.'}\n\nREVIEW PLAN\n1. Verify client-reported facts against evidence.\n2. Obtain treatment records, bills, coverage and incident evidence as relevant.\n3. Verify current primary authority and applicable court rules.\n4. Use the drafting studio to prepare a structured review draft.\n5. Supervising attorney must review before external use.\n\nSource: structured matter record ${m.id}; unverified, fictional demo.\nAsk your workspace administrator to enable the drafting assistant for a response tailored to your request.`;$('#copilotResult').hidden=false;$('#copilotResult').innerHTML=`<div class="panel-head"><h2>Prepared response · ${m.id}</h2>${badge('Attorney review required','amber')}</div><pre class="draft">${esc(answer)}</pre><div class="form-actions"><button class="button outline small" id="saveCopilotDraft">Save as review draft ↗</button><button class="button dark small" data-action="draft" data-key="${m.id}">Open drafting studio ↗</button></div>`;$('#saveCopilotDraft').onclick=async()=>{state.documents.unshift({id:id(),matter:m.id,name:'Copilot work product — '+m.name,type:'Draft',text:answer,created:today()});try{await save('Copilot draft saved',m.id);toast('Saved to matter documents for attorney review.')}catch(err){toast(err.message)}}}catch(err){toast(err.message)}finally{if(button.isConnected)button.disabled=false}}}
function overview(){let pending=state.tasks.filter(t=>!t.done);return heading('YOUR FIRM, IN FOCUS','A clearer view. <em>A stronger practice.</em>','One connected workspace, from first conversation to final resolution.',btn('New intake','intake'))+`<div class="stats-grid"><div class="stat"><p>OPEN MATTERS</p><strong>${state.matters.length}</strong><small>Across ${new Set(state.matters.map(m=>m.type)).size} practice areas</small></div><div class="stat"><p>INTAKE QUEUE</p><strong>${state.matters.filter(m=>m.stage==='Intake').length}</strong><small>Conflict check required</small></div><div class="stat"><p>OPEN TASKS</p><strong>${pending.length}</strong><small>Dates entered by team · not court-calculated</small></div><div class="stat"><p>REVIEW QUEUE</p><strong>${state.documents.filter(d=>d.type==='Draft').length+state.jobs.filter(j=>j.status==='Pending review').length}</strong><small>Attorney decisions stay with your team</small></div></div><div class="os-grid"><div><div class="panel"><div class="panel-head"><h2>Matters that need your attention</h2><button class="text-button" data-view="matters">All matters ↗</button></div>${matterTable(state.matters.slice(0,5))}</div><div class="panel"><div class="panel-head"><h2>Your next steps</h2><button class="text-button" data-view="tasks">View tasks ↗</button></div>${pending.slice(0,3).map(taskRow).join('')||'<p class="subtle">You’re up to date.</p>'}</div></div><div><div class="panel"><div class="panel-head"><h2>Connected matter intelligence</h2>${badge('Live from demo records')}</div><div class="graph-preview">${graphSvg(state.matters[0],true)}</div><p class="subtle">People, providers, insurers and evidence, connected around the matter.</p><button class="text-button" data-view="knowledge">Explore the knowledge graph ↗</button></div><div class="panel"><div class="panel-head"><h2>Workspace activity</h2></div>${state.audit.length?state.audit.slice(0,4).map(a=>`<div class="activity"><span>↗</span><p>${esc(a.action)}<small>${esc(a.detail)} · ${new Date(a.date).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</small></p></div>`).join(''):'<p class="subtle">Your activity appears here as you work. Try adding an intake or creating a document.</p>'}</div></div></div>`}
function matterTable(items){return table(['CLIENT / MATTER','PRACTICE AREA','STAGE','ATTORNEY'],items.map(m=>`<tr class="clickable" data-matter="${m.id}"><td><strong>${esc(m.name)}</strong><small>${m.id}</small></td><td>${esc(m.type)}</td><td>${badge(m.stage,m.stage==='Intake'?'amber':'')}</td><td>${esc(m.owner)}</td></tr>`).join(''))}
function matters(){return heading('MATTERS & INTAKE','Every story. <em>One place.</em>','A shared pipeline with client details, documents, tasks and communications.',btn('New intake','intake'))+`<div class="toolbar"><input id="matterSearch" aria-label="Search matters" placeholder="Search clients, matter IDs or practice areas…"><select id="stageFilter" aria-label="Filter stage"><option value="">All stages</option>${stages.map(s=>`<option>${s}</option>`).join('')}</select></div><div id="matterResults">${matterBoard(state.matters)}</div>`}
function matterBoard(items){return `<div class="kanban">${stages.map(s=>`<div class="kanban-col"><h3>${s}<span>${items.filter(m=>m.stage===s).length}</span></h3>${items.filter(m=>m.stage===s).map(m=>`<article class="matter-card" data-matter="${m.id}"><span class="badge gray">${m.id}</span><h4>${esc(m.name)}</h4><p>${esc(m.type)}<br>${esc(m.language)} · ${esc(m.owner)}</p><small>${esc(m.summary).slice(0,95)}…</small></article>`).join('')}</div>`).join('')}</div>`}
function showMatter(key){const m=state.matters.find(m=>m.id===key);if(!m)return;modal(`${m.id} / MATTER PROFILE`,`<h2>${esc(m.name)}</h2><p class="subtle">${esc(m.type)} · ${esc(m.language)}</p><div class="form-grid"><label>Stage<select id="matterStage">${stages.map(s=>`<option ${s===m.stage?'selected':''}>${s}</option>`).join('')}</select></label><label>Attorney<select id="matterOwner">${['Unassigned','Adnan Munawar','Junior attorney'].map(s=>`<option ${s===m.owner?'selected':''}>${s}</option>`).join('')}</select></label><label>Email<input id="matterEmail" type="email" value="${esc(m.email)}"></label><label>Phone<input id="matterPhone" value="${esc(m.phone)}"></label><label>Medical provider<input id="matterProvider" value="${esc(m.provider)}"></label><label>Insurer<input id="matterInsurer" value="${esc(m.insurer)}"></label><label class="full">Matter summary<textarea id="matterSummary" rows="3">${esc(m.summary)}</textarea></label></div><div class="form-actions"><button class="button outline small" data-action="draft" data-key="${m.id}">Create document</button><button class="button dark small" id="saveMatter">Save matter ↗</button></div><div class="timeline">${state.tasks.filter(t=>t.matter===key).map(t=>`<div>${esc(t.title)}<p>${esc(t.date)} · ${esc(t.owner)} · ${t.done?'Complete':'Open'}</p></div>`).join('')||'<p class="subtle">No tasks linked yet.</p>'}</div><p class="subtle">${state.documents.filter(d=>d.matter===key).length} documents · ${state.messages.filter(d=>d.matter===key).length} communications · ${currency(state.expenses.filter(e=>e.matter===key).reduce((n,e)=>n+e.amount,0))} expenses</p>`);$('#saveMatter').onclick=async()=>{try{const email=$('#matterEmail');if(!email.checkValidity()){email.reportValidity();return}Object.assign(m,{stage:$('#matterStage').value,owner:$('#matterOwner').value,email:email.value,phone:$('#matterPhone').value,provider:$('#matterProvider').value,insurer:$('#matterInsurer').value,summary:$('#matterSummary').value});await save('Matter updated',m.id);$('#modal').close();render();toast('Matter updated across the workspace.')}catch(e){toast(e.message)}}}
function intake(practice=''){modal('M LAW / FIRST CONVERSATION',`<h2>Let’s start <em>your next chapter.</em></h2><p class="subtle">Prototype intake. Use fictional information. This request is saved in this demo workspace; it is not sent to the law firm.</p><form id="intakeForm"><div class="form-grid"><label>Full name<input name="name" required maxlength="100" autocomplete="name"></label><label>Preferred language<select name="language">${['English','Español','اردو','हिन्दी','ਪੰਜਾਬੀ','العربية'].map(l=>`<option>${l}</option>`).join('')}</select></label><label>Email<input name="email" type="email" required maxlength="150"></label><label>Phone<input name="phone" type="tel" required maxlength="40"></label><label>What happened?<select name="type">${['Vehicle accidents','Construction accidents','Premises liability','Other personal injury'].map(p=>`<option ${p===practice?'selected':''}>${p}</option>`).join('')}</select></label><label>Incident date<input name="incident" type="date" max="${today()}" required></label><label class="full">Briefly tell us your story<textarea name="summary" maxlength="3000" rows="3" required></textarea></label><label class="check-label full"><input type="checkbox" required> I understand this is a demo, not a consultation or engagement agreement. I am using fictional information.</label></div><div class="form-actions"><button class="button dark" type="submit">Save demo intake ↗</button></div></form>`);$('#intakeForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const m={...f,id:'ML-'+Date.now().toString().slice(-7),stage:'Intake',owner:'Unassigned',provider:'Not recorded',insurer:'Not recorded',created:today()};state.matters.unshift(m);state.tasks.unshift({id:id(),title:'Conflict check & consultation: '+m.name,matter:m.id,owner:'Adnan Munawar',date:today(),done:false});try{await save('New intake received',m.id);modal('INTAKE SAVED',`<h2>Your story has <em>a starting point.</em></h2><p class="subtle">Demo record ${m.id} is now in the intake queue. A conflict-check task was created for the principal. No message has been sent to the firm.</p>${btn('See it in the firm OS','intakeComplete')}`);if(!$('#workspace').hidden)render()}catch(err){toast(err.message)}}}
function contacts(){const items=state.matters.flatMap(m=>[{name:m.name,role:'Client',detail:m.email,matter:m.id},{name:m.provider,role:'Medical provider',detail:'Records requests',matter:m.id},{name:m.insurer,role:'Insurer',detail:'Coverage / claims',matter:m.id}]).filter(x=>x.name!=='Not recorded');return heading('PEOPLE & PROVIDERS','Relationships, <em>in context.</em>','Every contact links back to a matter. Edit providers and insurers from the matter profile.')+`<div class="toolbar"><input id="contactSearch" aria-label="Search contacts" placeholder="Find a client, provider or insurer…"></div><div class="panel" id="contactResults">${contactTable(items)}</div>`}
function contactItems(){return state.matters.flatMap(m=>[{name:m.name,role:'Client',detail:m.email,matter:m.id},{name:m.provider,role:'Medical provider',detail:'Records requests',matter:m.id},{name:m.insurer,role:'Insurer',detail:'Coverage / claims',matter:m.id}]).filter(x=>x.name!=='Not recorded')}
function contactTable(items){return table(['NAME','RELATIONSHIP','DETAIL','LINKED MATTER'],items.map(x=>`<tr class="clickable" data-matter="${x.matter}"><td><strong>${esc(x.name)}</strong></td><td>${badge(x.role,'gray')}</td><td>${esc(x.detail)}</td><td>${esc(matterName(x.matter))}<small>${x.matter}</small></td></tr>`).join(''))}
function taskRow(t){return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" aria-label="Complete ${esc(t.title)}" data-task="${t.id}" ${t.done?'checked':''}><div><b>${esc(t.title)}</b><p>${esc(matterName(t.matter))} · ${esc(t.owner)}</p></div>${badge(t.date,t.date<today()&&!t.done?'red':'gray')}</div>`}
function tasks(){return heading('TASKS & DEADLINES','Keep the next move <em>in sight.</em>','Team-entered dates. Court deadlines must be independently verified by an attorney.',btn('Add task','newTask'))+`<div class="os-grid"><div class="panel"><div class="panel-head"><h2>Work queue</h2>${badge(state.tasks.filter(t=>!t.done).length+' open')}</div>${[...state.tasks].sort((a,b)=>a.done-b.done||a.date.localeCompare(b.date)).map(taskRow).join('')}</div><div class="panel"><div class="panel-head"><h2>Upcoming dates</h2><button class="text-button" data-action="calendarExport">Export .ics ↗</button></div>${[...state.tasks].filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)).map(t=>`<div class="activity"><div class="date-block">${new Date(t.date+'T12:00').toLocaleString('en-US',{month:'short'})}<b>${Number(t.date.slice(-2))}</b></div><p>${esc(t.title)}<small>${esc(matterName(t.matter))}</small></p></div>`).join('')}</div></div>`}
function newTask(){modal('WORKSPACE / NEW TASK',`<h2>Make the next step clear.</h2><form id="taskForm" class="form-stack"><label>Task<input name="title" required maxlength="250"></label><label>Matter<select name="matter">${matterOptions()}</select></label><div class="form-grid"><label>Owner<select name="owner"><option>Junior attorney</option><option>Adnan Munawar</option></select></label><label>Date<input type="date" name="date" required></label></div><p class="subtle">This date is manually entered. It is not a calculated legal deadline.</p><button class="button dark">Save task ↗</button></form>`);$('#taskForm').onsubmit=async e=>{e.preventDefault();state.tasks.unshift({...Object.fromEntries(new FormData(e.target)),id:id(),done:false});try{await save('Task created',state.tasks[0].title);$('#modal').close();render();toast('Task created.')}catch(e){toast(e.message)}}}
function documents(){return heading('DOCUMENTS & FILES','From information <em>to work product.</em>','Matter-linked files and source-aware drafts, held for attorney review.',btn('Create draft','draft'))+`<div class="upload-zone"><span class="module-icon">↥</span><h3>Add a matter file</h3><p>Text and PDF files · 5 MB maximum · ${mode==='browser'?'browser storage is limited':'stored on the local server'}</p><select id="uploadMatter" aria-label="Matter for upload">${matterOptions()}</select> <input id="fileUpload" type="file" accept=".txt,.pdf,.csv" aria-label="Upload matter file"></div><div class="panel"><div class="panel-head"><h2>Document library</h2>${badge('Review required','amber')}</div>${table(['DOCUMENT','MATTER','STATUS','ACTION'],[...state.documents.map(d=>`<tr><td><strong>${esc(d.name)}</strong><small>${esc(d.created)}</small></td><td>${esc(matterName(d.matter))}</td><td>${badge(d.type,d.type==='Draft'?'amber':'gray')}</td><td><button class="inline-link" data-document="${d.id}">Open ↗</button></td></tr>`),...state.files.map(f=>`<tr><td><strong>${esc(f.name)}</strong><small>${Math.round(f.size/1024)} KB</small></td><td>${esc(matterName(f.matter))}</td><td>${badge('Uploaded','gray')}</td><td><button class="inline-link" data-download-file="${f.id}">Download ↗</button></td></tr>`)].join(''))}</div>`}
function draftDialog(key=''){modal('DRAFTING STUDIO / ATTORNEY REVIEW',`<h2>Give the facts <em>a structure.</em></h2><p class="subtle">Templates use recorded matter facts. Missing evidence stays marked. The prototype does not verify citations or court rules, and does not file documents.</p><form id="draftForm" class="form-stack"><label>Matter<select name="matter">${matterOptions(key)}</select></label><label>Work product<select name="template"><option>Intake summary</option><option>Medical records request</option><option>Demand outline</option><option>Motion outline</option><option>Client update</option><option>Filing preparation checklist</option></select></label><label>Instructions<textarea name="instructions" placeholder="Describe what the attorney needs. Do not add facts that are not in the record." maxlength="4000"></textarea></label><button class="button dark">Prepare review draft ↗</button></form>`);$('#draftForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const m=state.matters.find(x=>x.id===f.matter);const relatedFiles=state.files.filter(x=>x.matter===m.id);let text=`DRAFT — ATTORNEY REVIEW REQUIRED\n${f.template.toUpperCase()}\n\nMatter: ${m.id}\nClient: ${m.name}\nPractice: ${m.type}\nIncident date (client-reported): ${m.incident}\n\nRECORDED FACTS\n${m.summary}\n\nRELATED ENTITIES\nProvider: ${m.provider}\nInsurer: ${m.insurer}\nResponsible attorney: ${m.owner}\n\nSOURCE REGISTER\nMatter intake: ${m.id} (client-reported; unverified)\n${relatedFiles.length?relatedFiles.map(x=>x.name+' (uploaded; contents not verified)').join('\n'):'No source files supplied.'}\n\n`;
 const outlines={'Intake summary':'REVIEW ITEMS\nConflict check; engagement terms; treatment details; incident location; evidence preservation.','Medical records request':`TO: ${m.provider}\nRE: ${m.name}\n\n[Insert approved recipient address and signed authorization.]\nPlease provide the records identified in the accompanying authorization.\n[Attorney must specify the treatment period, requested records and permitted delivery method.]`,'Demand outline':'LIABILITY\n[Attorney analysis with supporting evidence required.]\n\nMEDICAL CHRONOLOGY\n[Source records and date-by-date treatment required.]\n\nDAMAGES AND LIENS\n[Verified bills, wage records, coverage and liens required.]\n\nDEMAND\n[Attorney-approved amount and rationale required.]','Motion outline':'CAPTION\n[Confirm court, index number, parties and judge.]\n\nRELIEF REQUESTED\n[Attorney to specify.]\n\nFACTUAL BASIS\n[Source-linked evidence required.]\n\nLEGAL STANDARD AND ARGUMENT\n[Current primary authority and citation validation required.]\n\nEXHIBITS / SERVICE\n[Attorney and filing specialist verification required.]','Client update':`Dear ${m.name},\n\nYour matter is currently recorded in the ${m.stage.toLowerCase()} stage. Your legal team is reviewing the information in your file. Please contact the team with questions or new treatment information.\n\n[Confirm accuracy, preferred language and recipient before sending.]`,'Filing preparation checklist':'□ Attorney has reviewed every factual statement and citation\n□ Court, venue, index number, caption and relief confirmed\n□ Applicable rules and deadlines independently checked\n□ Exhibits, authorizations, signatures and redactions verified\n□ Service method, recipients and proof of service confirmed\n□ Filing specialist has validated local requirements\n□ Supervising attorney has authorized filing\n\nThis checklist does not certify filing readiness.'};text+=outlines[f.template]+`\n\nATTORNEY INSTRUCTIONS\n${f.instructions||'None supplied.'}\n\nSTATUS: REVIEW DRAFT. NOT FILED, SERVED, OR SENT.\nPrepared ${today()}.`;
 state.documents.unshift({id:id(),matter:m.id,name:f.template+' — '+m.name,type:'Draft',text,created:today()});try{await save('Draft prepared',m.id+' / '+f.template);showDocument(state.documents[0].id);if(!$('#workspace').hidden)render()}catch(e){toast(e.message)}}}
function showDocument(key){const d=state.documents.find(x=>x.id===key);if(!d)return;modal('DOCUMENT / '+d.matter,`<h2>${esc(d.name)}</h2><span class="draft-label">DRAFT · ATTORNEY REVIEW REQUIRED</span><label class="subtle" for="draftText">Edit the draft</label><textarea id="draftText" class="draft" style="width:100%;min-height:350px">${esc(d.text)}</textarea><div class="form-actions"><button class="button outline small" id="downloadDraft">Download .txt</button><button class="button outline small" id="printDraft">Print / PDF</button><button class="button dark small" id="saveDraft">Save edits ↗</button></div>`);$('#saveDraft').onclick=async()=>{d.text=$('#draftText').value;try{await save('Draft edited',d.id);toast('Draft saved. Attorney review still required.')}catch(e){toast(e.message)}};$('#downloadDraft').onclick=()=>download(d.name+'.txt',$('#draftText').value,'text/plain');$('#printDraft').onclick=()=>{const win=window.open('','_blank');if(!win){toast('Allow the print window to open.');return}win.document.write(`<!doctype html><title>${esc(d.name)}</title><style>body{max-width:750px;margin:50px auto;font:15px/1.8 Georgia;padding:25px}pre{white-space:pre-wrap;font:inherit}</style><pre>${esc($('#draftText').value)}</pre>`);win.document.close();win.print()}}
function communications(){return heading('CLIENT COMMUNICATIONS','Keep people <em>in the picture.</em>','Matter-linked updates with a review queue. No external messages are sent by this prototype.',btn('Compose update','compose'))+`<div class="os-grid"><div class="panel"><div class="panel-head"><h2>Communication drafts</h2>${badge('Outbox disconnected','amber')}</div>${state.messages.map(m=>`<div class="source-item"><a class="inline-link" data-matter="${m.matter}">${esc(matterName(m.matter))} · ${m.matter}</a><p>${esc(m.text)}</p><div class="toolbar" style="margin:12px 0 0">${badge(m.status,'amber')} ${badge(m.channel,'gray')}<span class="subtle">${esc(m.date)}</span></div></div>`).join('')||'<p class="subtle">No communication drafts.</p>'}</div><div><div class="panel"><h3>Concierge studio</h3><p class="subtle">Maya helps with inquiries, consultation bookings, callbacks and verified client updates.</p>${btn('Open concierge','concierge')}</div><div class="panel"><h3>Client portal preview</h3><p class="subtle">Preview a client’s matter status using fictional records. Identity verification and secure sign-in are required before a live client portal.</p><select id="portalMatter" aria-label="Client portal preview matter">${matterOptions()}</select><button class="text-button" id="portalPreview">Preview client view ↗</button></div></div></div>`}
function compose(){modal('COMMUNICATIONS / COMPOSE',`<h2>A clear update.</h2><form id="messageForm" class="form-stack"><label>Matter<select name="matter">${matterOptions()}</select></label><label>Channel<select name="channel"><option>Email draft</option><option>SMS draft</option><option>Portal draft</option></select></label><label>Message<textarea name="text" required maxlength="5000"></textarea></label><button class="button dark">Save to review queue ↗</button></form>`);$('#messageForm').onsubmit=async e=>{e.preventDefault();state.messages.unshift({...Object.fromEntries(new FormData(e.target)),id:id(),status:'Pending review',date:today()});try{await save('Client update drafted',state.messages[0].matter);$('#modal').close();render();toast('Draft saved. No message sent.')}catch(e){toast(e.message)}}}
function finance(){const total=state.expenses.reduce((n,e)=>n+e.amount,0);return heading('FINANCE & TIME','Know the work. <em>Know the cost.</em>','Matter expenses and time capture. This prototype is not a trust ledger, accounting system or payment processor.',btn('Record expense','expense'))+`<div class="stats-grid"><div class="stat"><p>RECORDED EXPENSES</p><strong>${currency(total)}</strong><small>Illustrative case costs</small></div><div class="stat"><p>TIME CAPTURED</p><strong>${(state.time.reduce((s,t)=>s+t.minutes,0)/60).toFixed(1)} h</strong><small>Internal matter time</small></div><div class="stat"><p>TRUST ACCOUNTING</p><strong>—</strong><small>Requires a validated ledger integration</small></div><div class="stat"><p>PAYMENTS</p><strong>—</strong><small>No processor connected</small></div></div><div class="os-grid"><div class="panel"><div class="panel-head"><h2>Case expenses</h2><button class="text-button" data-action="expenseExport">Export CSV ↗</button></div>${table(['DATE','MATTER','DESCRIPTION','AMOUNT'],state.expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(matterName(e.matter))}</td><td>${esc(e.description)}</td><td>${currency(e.amount)}</td></tr>`).join(''))}<div class="ledger-total"><span class="subtle">Recorded costs</span><strong>${currency(total)}</strong></div></div><div class="panel"><div class="panel-head"><h2>Time entries</h2><button class="text-button" data-action="timeEntry">Add time ↗</button></div>${state.time.map(t=>`<div class="source-item"><strong>${esc(t.description)}</strong><p>${esc(matterName(t.matter))} · ${t.minutes} minutes</p></div>`).join('')||'<p class="subtle">Record the work behind the matter, even on contingency cases.</p>'}</div></div>`}
function expense(time=false){modal('FINANCE / '+(time?'TIME ENTRY':'CASE EXPENSE'),`<h2>${time?'Capture the work.':'Record a case cost.'}</h2><form id="expenseForm" class="form-stack"><label>Matter<select name="matter">${matterOptions()}</select></label><label>Description<input name="description" required maxlength="250"></label><label>${time?'Minutes':'Amount (USD)'}<input name="amount" type="number" step="${time?'1':'.01'}" min="${time?'1':'.01'}" max="1000000" required></label><label>Date<input name="date" type="date" value="${today()}" required></label><button class="button dark">Save ${time?'time':'expense'} ↗</button></form>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));f.amount=Number(f.amount);f.id=id();if(time){f.minutes=f.amount;delete f.amount;state.time.unshift(f)}else state.expenses.unshift(f);try{await save(time?'Time captured':'Expense recorded',f.matter);$('#modal').close();render();toast('Entry saved.')}catch(e){toast(e.message)}}}
function graphSvg(m,small=false){if(!m)return '';const entities=[{label:m.name,type:'Client',x:330,y:70},{label:m.provider,type:'Provider',x:125,y:180},{label:m.insurer,type:'Insurer',x:535,y:180},{label:m.owner,type:'Attorney',x:145,y:350},{label:state.documents.filter(d=>d.matter===m.id).length+' documents',type:'Evidence',x:515,y:350}];return `<svg viewBox="0 0 660 440" class="${small?'':'ontology-svg'}" role="img" aria-label="Matter relationships"><g stroke="#b2c1a0" stroke-width="1">${entities.map(n=>`<line x1="330" y1="220" x2="${n.x}" y2="${n.y}"/>`).join('')}</g><g class="node" data-node="Matter"><circle cx="330" cy="220" r="49" fill="#284332"/><text x="330" y="217" fill="#eee5cf" text-anchor="middle">${esc(m.id)}</text><text x="330" y="234" fill="#b7c8a5" text-anchor="middle" style="font-size:8px">MATTER</text></g>${entities.map(n=>`<g class="node" data-node="${esc(n.type)}"><circle cx="${n.x}" cy="${n.y}" r="29" fill="#e3e9d8" stroke="#b7c6a3"/><text x="${n.x}" y="${n.y+4}" text-anchor="middle" fill="#536e41" style="font-size:9px">${esc(n.type)}</text><text x="${n.x}" y="${n.y+48}" text-anchor="middle" fill="#6b7f59">${esc(n.label.length>24?n.label.slice(0,23)+'…':n.label)}</text></g>`).join('')}</svg>`}
function knowledge(){return heading('MATTER INTELLIGENCE','A connected memory <em>for the firm.</em>','Explore the people, documents and responsibilities connected to each matter. Advanced legal knowledge requires certification.')+`<div class="toolbar"><select id="graphMatter" aria-label="Select graph matter">${matterOptions()}</select>${badge('Explicit relationships')} ${badge('Auto-extraction not connected','amber')}</div><div class="graph-layout"><div class="panel" id="graphArea">${graphSvg(state.matters[0])}</div><div><div class="panel" id="nodeDetail"><h3>Every fact has context.</h3><p class="subtle">Select a node to inspect its provenance and related records. The graph updates when you edit a matter or create documents.</p></div><div class="panel"><div class="panel-head"><h2>Ask the matter workspace</h2></div><p class="subtle">Queries below use structured records. For open-ended AI, connect the local server model.</p><form id="knowledgeForm" class="form-stack"><input aria-label="Matter question" placeholder="e.g. What is missing?" id="knowledgeQuestion" required><button class="button outline small">Inspect matter ↗</button></form><div id="knowledgeAnswer" class="subtle"></div></div></div></div>`}
const legalSources=[{name:'New York Official Reports',url:'https://www.nycourts.gov/reporter/decisions.htm',desc:'Primary judicial decisions. Proposed source; no feed connected.'},{name:'New York State Senate',url:'https://www.nysenate.gov/legislation/laws',desc:'Statutory text. Proposed source; changes require effective-date verification.'},{name:'New York State Unified Court System',url:'https://ww2.nycourts.gov/rules/index.shtml',desc:'Court rules. Manual verification before any filing or deadline change.'},{name:'OSHA newsroom',url:'https://www.osha.gov/news/newsreleases',desc:'Construction and workplace safety updates.'}];
function research(){return heading('LAW MONITOR','Stay current. <em>Keep the evidence.</em>','Source collection, provenance and a review queue. No legal update changes a matter automatically.',btn('Check configured sources','checkSources'))+`<div class="os-grid"><div class="panel"><div class="panel-head"><h2>Official source registry</h2>${badge('Manual registry','amber')}</div>${legalSources.map(s=>`<div class="source-item"><a href="${s.url}" target="_blank" rel="noopener">${s.name} ↗</a><p>${s.desc}</p></div>`).join('')}<p class="subtle">On the local server, set LAW_FEED_URLS to official RSS/Atom feeds and run the collector. The default registry is not an active feed subscription.</p></div><div class="panel"><div class="panel-head"><h2>Retrieved update batches</h2></div>${state.updates.length?state.updates.map(u=>`<div class="source-item"><a href="${esc(u.source)}" target="_blank" rel="noopener">${esc(u.title)} ↗</a><p>${esc(u.date)} · ${esc(u.status)}</p><p>${esc(u.summary)}</p></div>`).join(''):'<p class="subtle">No updates have been retrieved. There is no simulated “latest law” feed.</p>'}<div class="review-card"><b style="font-size:12px">Review before application</b><p>Verify jurisdiction, precedential weight, effective date and relevance. Only an attorney may approve changes to strategy or deadlines.</p></div></div></div>`}
const workflows=[{key:'intake',icon:'◌',title:'Intake & conflict preparation',desc:'Create an intake summary and queue conflict review. Representation requires attorney approval.'},{key:'records',icon:'▧',title:'Medical records follow-up',desc:'Prepare a source checklist and a request draft. Authorizations and recipients require review.'},{key:'demand',icon:'⎇',title:'Demand preparation',desc:'Build a structured outline from recorded facts. Missing evidence stays visible.'},{key:'client',icon:'♧',title:'Client status update',desc:'Create a matter-status message for review. No external sending is enabled.'},{key:'filing',icon:'☑',title:'Filing readiness review',desc:'Prepare a checklist for caption, sources, exhibits, signatures and service.'},{key:'law',icon:'◎',title:'Legal update review',desc:'Queue official-source review. No autonomous changes to legal analysis or deadlines.'}];
function agents(){return heading('CASE PREPARATION','Let the system prepare.<br><em>Let your team decide.</em>','Prepare linked drafts and next steps, then send the work to your legal team for review.')+`<div class="toolbar"><select id="workflowMatter" aria-label="Matter for workflow">${matterOptions()}</select>${badge('Preparation workflows')} ${badge('Review before external use','gray')}</div><div class="module-grid">${workflows.map(w=>`<div class="module-card"><span class="module-icon">${w.icon}</span><h3>${w.title}</h3><p>${w.desc}</p><button class="button outline small" data-workflow="${w.key}">Prepare workflow ↗</button></div>`).join('')}</div><div class="panel" style="margin-top:25px"><div class="panel-head"><h2>Workflow review queue</h2>${badge('Human approval boundary','amber')}</div>${table(['WORKFLOW','MATTER','STATE','OUTPUT'],state.jobs.map(j=>`<tr><td><strong>${esc(j.title)}</strong><small>${esc(j.date)}</small></td><td>${esc(matterName(j.matter))}</td><td>${badge(j.status,'amber')}</td><td><button class="inline-link" data-job="${j.id}">Review output ↗</button></td></tr>`).join(''))}</div>`}
async function runWorkflow(key){const m=state.matters.find(m=>m.id===$('#workflowMatter').value), w=workflows.find(w=>w.key===key);const task={id:id(),matter:m.id,title:w.title+' — review prepared output',owner:m.owner==='Unassigned'?'Adnan Munawar':m.owner,date:today(),done:false};state.tasks.unshift(task);let doc=null,msg=null;if(key==='client'){msg={id:id(),matter:m.id,channel:'Portal draft',text:`Hello ${m.name}, your matter is recorded in the ${m.stage.toLowerCase()} stage. Your legal team will confirm the next step. [Verify before sending.]`,status:'Pending review',date:today()};state.messages.unshift(msg)}else{doc={id:id(),matter:m.id,name:w.title+' — '+m.name,type:'Draft',created:today(),text:`DRAFT — ATTORNEY REVIEW REQUIRED\n${w.title}\n\nMatter: ${m.id} / ${m.name}\n${m.summary}\n\nSOURCE: Matter intake only (client-reported; unverified).\n\n${w.desc}\n\nCHECKLIST\n□ Verify matter facts and supporting documents\n□ Complete conflict / authorization checks as applicable\n□ Confirm current law, court rules and deadline calculations\n□ Review with supervising attorney\n\nNo message sent, no legal conclusion verified, no filing made.`};state.documents.unshift(doc)}const job={id:id(),title:w.title,matter:m.id,status:'Pending review',date:today(),document:doc?.id,message:msg?.id};state.jobs.unshift(job);try{await save('Workflow prepared',w.title+' / '+m.id);render();toast('Review task and linked work product created.')}catch(e){toast(e.message)}}
function connectors(){const services=[['Reception & intake','Capture inquiries, request callbacks and reserve consultations.','Available in this workspace'],['Voice conversations','Listen to Maya’s samples; use live speech when voice service is configured.',statusInfo.voiceConfigured?'Configured':'Samples available · live setup pending'],['Drafting assistant','Prepare request-specific work product from the selected matter.',statusInfo.modelConfigured?'Configured':'Setup required'],['Client verification','Send a one-time code to the registered contact before sharing approved updates.',statusInfo.verificationConfigured?'Configured':'Delivery setup required'],['Legal knowledge','Inspect matter relationships and prepare a certified legal knowledge layer.',statusInfo.ontologyConfigured?'Connection configured · review required':'Matter graph available'],['Legal updates','Collect official-source changes for legal review.',statusInfo.lawFeedsConfigured?'Sources configured':'Sources to select'],['Firm telephone','Forward the existing number after test calls and escalation checks.','Connection deferred'],['Staff access','Individual accounts and role checks in the private firm workspace.',statusInfo.accountMode?'Named accounts enabled':'Demonstration access']];return heading('M LAW / SERVICE STATUS','A connected firm.<br><em>A clear view.</em>','See which services are available and which need setup before live use.')+`<div class="module-grid">${services.map(([title,detail,status])=>`<article class="module-card"><span class="module-icon">⌘</span><h3>${esc(title)}</h3><p>${esc(detail)}</p>${badge(status,status.includes('required')||status.includes('pending')?'amber':'gray')}</article>`).join('')}</div><div class="panel" style="margin-top:25px"><h3>Ready at the right time</h3><p class="subtle">Availability here describes this workspace. Your team must complete the agreed security, language, document and workflow checks before live adoption.</p><button class="button outline small" data-view="onboarding">Open onboarding plan ↗</button></div>`;}
function settings(){return heading('M LAW / WORKSPACE','Your firm.<br><em>Your information.</em>','Keep a portable copy of your records and review workspace activity.')+`<div class="os-grid"><div class="panel"><h3>Workspace controls</h3><div class="settings-row"><div>Records<p>${mode==='server'?'Records are saved in this private firm workspace.':'Demonstration records are saved in this browser only.'}</p></div>${badge(mode==='server'?'Private workspace':'Browser demonstration')}</div><div class="settings-row"><div>Export records<p>Includes linked matters, drafts, tasks and activity. Store exports securely.</p></div>${btn('Download records','export')}</div><div class="settings-row"><div>Restore the fictional examples<p>Replaces demo records. Export your work first.</p></div><button class="button outline small" data-action="reset" ${statusInfo.accountMode?'disabled title="Use an isolated demonstration workspace"':''}>Restore demo</button></div></div><div class="panel"><h3>Staff access & continuity</h3><p class="subtle">${statusInfo.accountMode?'Individual staff sign-in is enabled. Your account role determines the actions available.':'This is a demonstration workspace. Individual staff accounts are available in the private pilot setup.'}</p><p class="subtle">Backups, recovery checks and onboarding decisions are managed in the launch plan. Additional sign-in protection, matter restrictions and independent security review remain required before confidential live use.</p><button class="button dark small" data-view="onboarding">Open launch plan ↗</button></div></div><div class="panel"><div class="panel-head"><h2>Workspace activity</h2>${badge('Activity history','gray')}</div>${table(['TIME','ACTION','DETAIL'],state.audit.slice(0,50).map(a=>`<tr><td>${esc(new Date(a.date).toLocaleString())}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join(''))}</div>`;}
const greetings={'English':'Hello. I’m the M Law demo concierge. I can help you start an intake, find office information, or request a callback. I’m not a lawyer. Please use fictional information. How can I help?','Español':'Hola. Soy el asistente de demostración de M Law. Puedo ayudarle a iniciar una consulta o encontrar información de la oficina. No soy abogado. Use datos ficticios. ¿Cómo puedo ayudarle?','اردو':'السلام علیکم۔ میں ایم لا کا ڈیمو معاون ہوں۔ میں ابتدائی معلومات اور دفتر کی تفصیلات میں مدد کر سکتا ہوں۔ میں وکیل نہیں ہوں۔ براہ کرم فرضی معلومات استعمال کریں۔','हिन्दी':'नमस्ते। मैं M Law का डेमो सहायक हूँ। मैं शुरुआती जानकारी और कार्यालय के विवरण में मदद कर सकता हूँ। मैं वकील नहीं हूँ। कृपया काल्पनिक जानकारी का उपयोग करें।','ਪੰਜਾਬੀ':'ਸਤ ਸ੍ਰੀ ਅਕਾਲ। ਮੈਂ M Law ਦਾ ਡੈਮੋ ਸਹਾਇਕ ਹਾਂ। ਮੈਂ ਸ਼ੁਰੂਆਤੀ ਜਾਣਕਾਰੀ ਅਤੇ ਦਫ਼ਤਰ ਦੇ ਵੇਰਵਿਆਂ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹਾਂ। ਮੈਂ ਵਕੀਲ ਨਹੀਂ ਹਾਂ। ਕਿਰਪਾ ਕਰਕੇ ਕਾਲਪਨਿਕ ਜਾਣਕਾਰੀ ਵਰਤੋ।','العربية':'مرحباً. أنا مساعد M Law التجريبي. يمكنني المساعدة في بدء الاستفسار والعثور على معلومات المكتب. لست محامياً. يرجى استخدام معلومات خيالية.'};
function legacyConcierge(){chatHistory=[{role:'assistant',content:greetings[chatLanguage]}];modal('M LAW / CONCIERGE STUDIO',`<div class="chat-controls"><select id="chatLanguage" aria-label="Conversation language">${Object.keys(greetings).map(l=>`<option ${l===chatLanguage?'selected':''}>${l}</option>`).join('')}</select><span class="status">${statusInfo.modelConfigured?'Configured model · server':'Scripted demo · no AI connected'}</span></div><div class="messages" id="chatMessages" aria-live="polite"></div><form id="chatForm" class="assistant-box"><input id="chatInput" aria-label="Message concierge" placeholder="Tell us how we can help…" required maxlength="2000"><button class="button dark small" aria-label="Send message">↗</button></form><div class="toolbar" style="margin:15px 0 0"><button class="text-button" data-action="intake">Start demo intake ↗</button><button class="text-button" id="readAloud">Read aloud ◌</button><button class="text-button" id="callback">Request callback ↗</button></div><p class="subtle">Not legal advice. No access to confidential client records. Speech uses available device voices; offline availability and languages vary. Phone service is not connected.</p>`);chatRender();$('#chatLanguage').onchange=e=>{chatLanguage=e.target.value;chatHistory=[{role:'assistant',content:greetings[chatLanguage]}];chatRender()};$('#chatForm').onsubmit=sendChat;$('#readAloud').onclick=()=>{if(!('speechSynthesis'in window)){toast('Device speech is unavailable.');return}const lang={'English':'en-US','Español':'es-US','اردو':'ur-PK','हिन्दी':'hi-IN','ਪੰਜਾਬੀ':'pa-IN','العربية':'ar-SA'}[chatLanguage];speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(chatHistory.filter(m=>m.role==='assistant').at(-1).content);u.lang=lang;speechSynthesis.speak(u)};$('#callback').onclick=()=>intake()}
function chatRender(){if(!$('#chatMessages'))return;$('#chatMessages').innerHTML=chatHistory.map(m=>`<div class="message ${m.role==='user'?'user':''}" dir="auto">${esc(m.content)}</div>`).join('');$('#chatMessages').scrollTop=99999}
async function sendChat(e){e.preventDefault();const input=$('#chatInput'),text=input.value.trim();if(!text)return;chatHistory.push({role:'user',content:text});input.value='';chatRender();const b=$('#chatForm button');b.disabled=true;try{let content;if(mode==='server'&&statusInfo.modelConfigured){const r=await apiFetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:chatHistory.slice(-12),language:chatLanguage})});const result=await r.json();if(!r.ok)throw Error(result.error||'Model unavailable');content=result.content}else{if(chatLanguage==='English'){content=/office|address|location/i.test(text)?'The firm lists 420 Lexington Avenue, Suite 1402, New York (by appointment), and 100 Jericho Quadrangle, Suite 316, Jericho. Phone: 212-400-4000.':/fee|cost|pay/i.test(text)?'The firm advertises “no win, no fee.” Exact fees and expenses require review of an engagement agreement with an attorney.':/status|case|hearing/i.test(text)?'This public demo cannot access private case information. Use the fictional client portal preview in the firm workspace, or contact the firm for a real matter.':'I can help prepare an intake for attorney review. Use “Start demo intake” below to share fictional incident and contact details. The demo saves a record and conflict-check task; it does not contact the firm.'}else{const answers={'Español':'Puede iniciar un registro ficticio con “Start demo intake”. El equipo debe revisar los conflictos y los hechos. Para asuntos reales, llame al 212-400-4000. No puedo acceder a expedientes privados.','اردو':'فرضی ابتدائی درخواست کے لیے “Start demo intake” منتخب کریں۔ حقیقی معاملے کے لیے 212-400-4000 پر رابطہ کریں۔ میں نجی مقدمات تک رسائی نہیں رکھتا۔','हिन्दी':'काल्पनिक जानकारी के साथ “Start demo intake” चुनें। वास्तविक मामले के लिए 212-400-4000 पर संपर्क करें। मैं निजी फाइलें नहीं देख सकता।','ਪੰਜਾਬੀ':'ਕਾਲਪਨਿਕ ਜਾਣਕਾਰੀ ਨਾਲ “Start demo intake” ਚੁਣੋ। ਅਸਲ ਮਾਮਲੇ ਲਈ 212-400-4000 ਤੇ ਸੰਪਰਕ ਕਰੋ। ਮੈਂ ਨਿੱਜੀ ਫਾਈਲਾਂ ਨਹੀਂ ਦੇਖ ਸਕਦਾ।','العربية':'لبدء طلب تجريبي اختر “Start demo intake” واستخدم بيانات خيالية. للقضايا الحقيقية اتصل على 212-400-4000. لا يمكنني الوصول إلى الملفات الخاصة.'};content=answers[chatLanguage]}}chatHistory.push({role:'assistant',content});chatRender()}catch(err){chatHistory.push({role:'assistant',content:'The configured model could not respond. No fallback provider was used. '+err.message});chatRender()}finally{if(b.isConnected)b.disabled=false}}
async function click(e){const b=e.target.closest('[data-action],[data-view],[data-matter],[data-practice],[data-document],[data-task],[data-workflow],[data-job],[data-node],[data-download-file]');if(!b)return;try{
 if(b.dataset.view){openWorkspace(b.dataset.view);return}if(b.dataset.matter){showMatter(b.dataset.matter);return}if(b.dataset.practice){intake(b.dataset.practice);return}if(b.dataset.document){showDocument(b.dataset.document);return}if(b.dataset.task){const t=state.tasks.find(t=>t.id===b.dataset.task);t.done=b.checked;await save('Task '+(t.done?'completed':'reopened'),t.title);return}if(b.dataset.workflow){await runWorkflow(b.dataset.workflow);return}if(b.dataset.downloadFile){await downloadFile(b.dataset.downloadFile);return}if(b.dataset.job){const j=state.jobs.find(x=>x.id===b.dataset.job);if(j.document)showDocument(j.document);else modal('WORKFLOW OUTPUT',`<h2>${esc(j.title)}</h2><p class="subtle">${esc(state.messages.find(m=>m.id===j.message)?.text||'No output')}</p>${badge('Pending attorney review','amber')}`);return}if(b.dataset.node){const m=state.matters.find(m=>m.id===($('#graphMatter')?.value||state.matters[0].id));$('#nodeDetail')&&( $('#nodeDetail').innerHTML=`<h3>${esc(b.dataset.node)}</h3><p class="subtle">Linked to ${esc(m.name)} · ${m.id}<br>Provenance: manually entered demo matter record.<br>Extraction: none. Confidence: not assigned.<br>Documents: ${state.documents.filter(d=>d.matter===m.id).length}.<br>Attorney: ${esc(m.owner)}.</p><button class="inline-link" data-matter="${m.id}">Inspect matter ↗</button>`);return}
 const a=b.dataset.action;if(a==='home')home();if(a==='workspace')openWorkspace();if(a==='intake')intake();if(a==='intakeComplete'){$('#modal').close();openWorkspace('matters')}if(a==='concierge')concierge();if(a==='newTask')newTask();if(a==='draft')draftDialog(b.dataset.key);if(a==='compose')compose();if(a==='expense')expense();if(a==='timeEntry')expense(true);if(a==='export')download('mlaw-workspace-'+today()+'.json',JSON.stringify(state,null,2),'application/json');if(a==='reset')resetDialog();if(a==='calendarExport')calendarExport();if(a==='expenseExport')download('mlaw-expenses.csv','Date,Matter,Description,Amount\r\n'+state.expenses.map(e=>[e.date,e.matter,e.description,e.amount].map(csv).join(',')).join('\r\n'),'text/csv');if(a==='checkSources'){if(mode!=='server'){toast('Source collection requires the local server and configured LAW_FEED_URLS.');return}b.disabled=true;try{const r=await apiFetch('/api/research/refresh',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error);const sr=await apiFetch('/api/state');state=await sr.json();render();toast(d.message)}finally{b.disabled=false}}}catch(err){toast(err.message)}}
function bindView(){if(view==='matters'){const update=()=>{const q=$('#matterSearch').value.toLowerCase(),stage=$('#stageFilter').value;$('#matterResults').innerHTML=matterBoard(state.matters.filter(m=>(!stage||m.stage===stage)&&[m.name,m.id,m.type,m.owner].join(' ').toLowerCase().includes(q)))};$('#matterSearch').oninput=update;$('#stageFilter').onchange=update}if(view==='contacts')$('#contactSearch').oninput=e=>$('#contactResults').innerHTML=contactTable(contactItems().filter(c=>JSON.stringify(c).toLowerCase().includes(e.target.value.toLowerCase())));if(view==='documents')$('#fileUpload').onchange=uploadFile;if(view==='knowledge'){$('#graphMatter').onchange=e=>{$('#graphArea').innerHTML=graphSvg(state.matters.find(m=>m.id===e.target.value))};$('#knowledgeForm').onsubmit=e=>{e.preventDefault();const m=state.matters.find(m=>m.id===$('#graphMatter').value);$('#knowledgeAnswer').textContent=`${m.name}: ${m.stage}. Attorney: ${m.owner}. ${state.documents.filter(d=>d.matter===m.id).length} documents, ${state.files.filter(d=>d.matter===m.id).length} source files, ${state.tasks.filter(d=>d.matter===m.id&&!d.done).length} open tasks. Missing: verified evidence, citation review and court rules are not supplied in this demo. Source: structured matter record ${m.id}.`}}if(view==='communications')$('#portalPreview').onclick=()=>{const m=state.matters.find(x=>x.id===$('#portalMatter').value);modal('FICTIONAL CLIENT PORTAL / PREVIEW',`<h2>Hello, ${esc(m.name.split(' ')[0])}.</h2><p class="subtle">A preview of your case’s next chapter.</p>${badge(m.stage)}<div class="timeline"><div>We’re working on your matter.<p>${esc(m.type)} · ${m.id}</p></div><div>Your legal team<p>${esc(m.owner)}</p></div><div>Stay connected<p>For new information, contact the firm directly. This preview is not a secure client account.</p></div></div><p class="subtle">Only approved external messages would appear here in production. Internal drafts are not shared.</p>`)}}
async function uploadFile(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Maximum file size is 5 MB.');return}if(!/\.(txt|pdf|csv)$/i.test(file.name)){toast('Use a text, PDF or CSV file.');return}if(mode==='browser'&&file.size>1500000){toast('Browser demo limit is 1.5 MB per file. Use the local server for larger files.');return}const f={id:id(),name:file.name,size:file.size,matter:$('#uploadMatter').value,type:file.type,created:today()};try{if(mode==='server'){const r=await apiFetch('/api/files/'+f.id,{method:'PUT',headers:{'Content-Type':'application/octet-stream'},body:file});if(!r.ok)throw Error('File upload failed')}else{f.data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}state.files.unshift(f);await save('File added',f.name+' / '+f.matter);render();toast('File linked to matter. Contents have not been analyzed.')}catch(err){toast(err.message)}}
async function downloadFile(key){const f=state.files.find(f=>f.id===key);if(mode==='server'){const r=await apiFetch('/api/files/'+key);if(!r.ok){toast('File unavailable.');return}downloadBlob(f.name,await r.blob())}else{const a=document.createElement('a');a.href=f.data;a.download=f.name;a.click()}}
function csv(v){return '"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,'\t$&')+'"'}
function downloadBlob(name,blob){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function download(name,text,type){downloadBlob(name,new Blob([text],{type}))}
function calendarExport(){const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let ics='BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//MLaw//Prototype//EN\r\n';for(const t of state.tasks.filter(t=>!t.done))ics+=`BEGIN:VEVENT\r\nUID:${t.id}@mlaw-prototype\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]|\.\d{3}/g,'')}\r\nDTSTART;VALUE=DATE:${t.date.replaceAll('-','')}\r\nSUMMARY:${clean(t.title)}\r\nDESCRIPTION:${clean('DEMO — manually entered; not a verified court deadline. '+t.matter)}\r\nEND:VEVENT\r\n`;download('mlaw-dates.ics',ics+'END:VCALENDAR\r\n','text/calendar')}
function resetDialog(){modal('RESTORE FICTIONAL EXAMPLES',`<h2>Restore the demonstration?</h2><p class="subtle">This replaces demonstration records. Download your records or create a backup first.</p><div class="form-actions"><button class="button outline" id="cancelReset">Keep records</button><button class="button dark" id="confirmReset">Restore examples</button></div>`);$('#cancelReset').onclick=()=>$('#modal').close();$('#confirmReset').onclick=async()=>{try{if(mode==='server'){const r=await apiFetch('/api/demo/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirm:'RESTORE DEMO'})});const d=await r.json();if(!r.ok)throw Error(d.error);state=d;}else{state=await fetch('/seed.json').then(r=>r.json());await save('Demo restored','Fictional examples');}$('#modal').close();render();toast('Fictional examples restored.');}catch(e){toast(e.message);}};}
initialize().catch(e=>{document.body.innerHTML='<p style="padding:40px">The prototype could not load. Please refresh. '+esc(e.message)+'</p>'});
async function concierge(){const {openMaya}=await import('/maya-ui.mjs');await openMaya({modal,read:()=>state,write:async s=>{state=s;await save('Reception workspace updated','Maya');},mode,voiceConfigured:statusInfo.voiceConfigured,refresh:async()=>{const r=await apiFetch('/api/state');if(!r.ok)throw Error('Workspace refresh failed');state=await r.json();if(!$('#workspace').hidden)render()},toast})}
function reception(){const appointments=state.appointments||[],calls=state.calls||[];return heading('MAYA / RECEPTION & CALENDAR','A warm welcome.<br><em>A connected next step.</em>','Your built-in reception desk, lead intake and consultation calendar.',btn('Talk to Maya','concierge'))+`<div class="reception-hero"><div><p class="eyebrow">CALM. ATTENTIVE. ALWAYS CLEAR.</p><h2>She listens. The firm stays connected.</h2><p>Lead capture · consultation booking · approved case updates · callback requests<br>Existing telephone number will be forwarded later. No carrier is connected.</p><div class="reception-kpis"><div><strong>${appointments.filter(a=>a.status==='Reserved').length}</strong><small>RESERVATIONS</small></div><div><strong>${calls.filter(c=>c.status==='Callback requested').length}</strong><small>CALLBACKS</small></div><div><strong>${state.matters.filter(m=>m.source==='Maya receptionist').length}</strong><small>MAYA LEADS</small></div></div></div><div class="agent-orb"><span>m</span></div></div><div class="os-grid"><div><div class="panel"><div class="panel-head"><h2>Consultation calendar</h2>${badge('America/New_York')}</div>${appointments.length?appointments.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(a=>`<div class="appointment-row"><div><strong>${esc(a.name)}</strong><p>${esc(new Date(a.start).toLocaleString('en-US',{timeZone:'America/New_York'}))} ET · 30 min<br>${esc(a.phone)} · ${esc(a.resource)}</p>${badge(a.status,a.status==='Cancelled'?'gray':'')}</div>${a.status==='Reserved'?`<button class="inline-link" data-cancel-appointment="${a.id}">Cancel reservation</button>`:''}</div>`).join(''):'<p class="subtle">Maya can reserve a weekday consultation between 9 am and 5 pm New York time. Try a booking to see it here.</p>'}</div><div class="panel"><div class="panel-head"><h2>Callback inbox</h2></div>${calls.map(c=>`<div class="appointment-row"><div><strong>${esc(c.name)}</strong><p>${esc(c.phone)} · ${esc(c.language)}<br>${esc(c.summary)}</p>${badge(c.status)}</div>${c.status==='Callback requested'?`<button class="inline-link" data-complete-callback="${c.id}">Mark returned</button>`:''}</div>`).join('')||'<p class="subtle">Callback requests appear here with the caller’s confirmed details.</p>'}</div></div><div><div class="panel"><div class="panel-head"><h2>Client-approved updates</h2><button class="text-button" id="publishClientUpdate">Add update ↗</button></div>${(state.clientUpdates||[]).map(u=>`<div class="source-item"><strong style="font-size:12px">${esc(matterName(u.matter))}</strong><p>${esc(u.text)}</p>${badge('Approved for client','gray')}<small class="subtle"> ${esc(u.date)}</small></div>`).join('')}<p class="subtle">Maya reads only these approved updates after verification. Internal notes and draft documents are excluded.</p></div><div class="panel"><h3>Reception readiness</h3><div class="maya-rule"><span>01</span><p>Built-in calendar and intake writes are active in this workspace.</p></div><div class="maya-rule"><span>02</span><p>${statusInfo.voiceConfigured?'Voice conversations are configured. Confirm each language and the voice quality before live use.':'Listen to the generated female voice sample. Live microphone conversations require voice setup.'}</p></div><div class="maya-rule"><span>03</span><p>${statusInfo.verificationConfigured?'Verification delivery configured; delivery receipts are checked before codes are accepted.':'Live verification delivery is not connected. Case status stays private; browser preview uses explicitly fictional codes.'}</p></div><div class="maya-rule"><span>04</span><p>Maya works with the firm’s intake and calendar. Connecting the existing telephone number and testing live calls remain outstanding.</p></div></div></div></div>`}
function bindReception(){const root=$('#osContent');root.onclick=async e=>{const cancel=e.target.closest('[data-cancel-appointment]'),complete=e.target.closest('[data-complete-callback]');try{if(cancel){const a=state.appointments.find(a=>a.id===cancel.dataset.cancelAppointment);a.status='Cancelled';await save('Appointment cancelled',a.id);render();toast('Calendar slot released. No external notification sent.')}if(complete){const c=state.calls.find(c=>c.id===complete.dataset.completeCallback);c.status='Returned by team';await save('Callback marked returned',c.id);render()}}catch(err){toast(err.message)}};$('#publishClientUpdate').onclick=()=>{modal('CLIENT COMMUNICATION / APPROVED UPDATE',`<h2>A verified update for the client.</h2><form id="clientUpdateForm" class="form-stack"><label>Matter<select name="matter">${matterOptions()}</select></label><label>Client-facing update<textarea name="text" required maxlength="1500" placeholder="Only information approved to share with this client."></textarea></label><label class="check-label"><input type="checkbox" required>I have reviewed this text and approve it for the verified client.</label><button class="button dark">Publish client update ↗</button></form>`);$('#clientUpdateForm').onsubmit=async e=>{e.preventDefault();state.clientUpdates??=[];const f=Object.fromEntries(new FormData(e.target));state.clientUpdates.unshift({...f,id:id(),approved:true,date:new Date().toISOString()});try{await save('Client update approved',f.matter);$('#modal').close();render();toast('Approved text is available after client verification.')}catch(err){toast(err.message)}}}}

function onboarding(){return heading('FIRM ONBOARDING','A considered start.<br><em>A connected firm.</em>','Prepare the meeting, map the first pilot and track the steps to live adoption.')+'<div id="onboardingApp"></div>';}
function approvals(){return heading('ATTORNEY REVIEW','Clear work product.<br><em>Explicit decisions.</em>','Version-bound internal review, with an accountable reviewer and a recorded decision.')+'<div id="approvalApp"></div>';}
async function bindOnboarding(target){const ui=await import('/onboarding-ui.mjs'),root=document.querySelector(target==='onboarding'?'#onboardingApp':'#approvalApp');if(!root)return;const ctx={read:()=>state,write:async(s,action)=>{state=s;await save(action,'Firm onboarding');},mode,status:statusInfo,toast,modal,api:apiFetch,go:key=>openWorkspace(key),refresh:async()=>{const r=await apiFetch('/api/state');if(!r.ok)throw Error('Workspace refresh failed.');state=await r.json();}};(target==='onboarding'?ui.mountOnboarding:ui.mountApprovals)(root,ctx);}
